 * PreCompact hook: saves state before context compaction.
 *
 * When Claude compacts context, important state can get lost in summarization.
 * This hook logs the compaction event and re-injects critical orientation
 * so the agent doesn't lose its bearings after compaction.
 */
const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..', '..');
const RECORDS = path.join(REPO_ROOT, 'operations', 'engineering', 'records');
const STATE_DIR = path.join(RECORDS, 'session-state');
const HISTORY_DIR = path.join(STATE_DIR, 'history');

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    // Log compaction event
    const now = new Date();
    const dateStr = now.toISOString().slice(0, 10);
    const timeStr = now.toISOString().slice(11, 19);

    if (fs.existsSync(HISTORY_DIR)) {
      const logFile = path.join(HISTORY_DIR, `${dateStr}.jsonl`);
      const entry = JSON.stringify({
        event: 'compaction',
        timestamp: now.toISOString(),
      });
      fs.appendFileSync(logFile, entry + '\n');
    }

    // Re-inject critical orientation after compaction
    const orientation = [
      'CRITICAL ORIENTATION (post-compaction refresh):',
      'Memory: operations/engineering/records/memory/ (NOT ~/.claude/)',
      'Harness source: operations/engineering/fars/agentic/ (NEVER edit .claude/)',
      'Library: library/ | Plans: operations/engineering/records/plans/',
      'Read AGENTS.md and SOUL.md if you need to re-orient.',
    ].join('\n');

    process.stderr.write(`[pre-compact] State saved at ${timeStr}. Orientation re-injected.\n`);
    process.stdout.write(orientation);
  } catch (e) {
    process.stderr.write(`[pre-compact] ${e.message}\n`);
  }
  process.exit(0);
});
"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\cost-tracker.js","content":"/**
 * Stop hook: tracks token and cost metrics per session.
 * Appends to session-state history so we can see what sessions actually cost.
 */
const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..', '..');
const RECORDS = path.join(REPO_ROOT, 'operations', 'engineering', 'records');
const STATE_DIR = path.join(RECORDS, 'session-state');
const HISTORY_DIR = path.join(STATE_DIR, 'history');

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw);
    const now = new Date();
    const dateStr = now.toISOString().slice(0, 10);

    // Extract what we can from the stop event
    const entry = {
      event: 'stop',
      timestamp: now.toISOString(),
      session_id: input.session_id || 'unknown',
    };

    // Append to daily history
    if (!fs.existsSync(HISTORY_DIR)) {
      fs.mkdirSync(HISTORY_DIR, { recursive: true });
    }
    const logFile = path.join(HISTORY_DIR, `${dateStr}.jsonl`);
    fs.appendFileSync(logFile, JSON.stringify(entry) + '\n');
  } catch (e) {
    process.stderr.write(`[cost-tracker] ${e.message}\n`);
  }
  process.exit(0);
});
"}

