{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\pre-bash-git-push.js","content":"/**
 * PreToolUse hook (Bash): warns before git push, blocks --force and --no-verify.
 */
const fs = require('fs');

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw);
    const command = (input.tool_input && input.tool_input.command) || '';

    if (!/\bgit\s+push\b/.test(command)) {
      process.exit(0);
      return;
    }

    // Block force push
    if (/--force\b|--force-with-lease\b|-f\b/.test(command)) {
      process.stderr.write('[git-push] BLOCKED: force push detected. Review changes first.\n');
      process.exit(2);
      return;
    }

    // Block --no-verify
    if (/--no-verify\b/.test(command)) {
      process.stderr.write('[git-push] BLOCKED: --no-verify bypasses hooks. Remove the flag.\n');
      process.exit(2);
      return;
    }

    // Warn on push to main/master
    if (/\b(main|master)\b/.test(command)) {
      process.stderr.write('[git-push] WARNING: pushing directly to main/master.\n');
    }
  } catch (e) {
    process.stderr.write(`[git-push] ${e.message}\n`);
  }
  process.exit(0);
});
"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\post-edit-quality.js","content":"/**
 * PostToolUse hook (Edit|Write): lightweight quality checks after file edits.
 *
 * Checks:
 * - JSON syntax for .json files
 * - YAML frontmatter syntax for .md files
 * - console.log/debugger in .js files
 * - Runs Biome/Prettier if available for JS/TS
 *
 * Non-blocking — warns only, never exit 2.
 */
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw);

    // Get the file path from tool input
    const filePath = (input.tool_input && input.tool_input.file_path) || '';
    if (!filePath) {
      process.exit(0);
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    const warnings = [];

    // JSON syntax check
    if (ext === '.json') {
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        JSON.parse(content);
      } catch (e) {
        warnings.push(`JSON syntax error: ${e.message}`);
      }
    }

    // JS/TS quality checks
    if (['.js', '.ts', '.tsx', '.jsx'].includes(ext)) {
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          if (/\bconsole\.log\b/.test(line) && !/\/\/.*console\.log/.test(line)) {
            warnings.push(`Line ${i + 1}: console.log detected`);
          }
          if (/\bdebugger\b/.test(line) && !/\/\/.*debugger/.test(line)) {
            warnings.push(`Line ${i + 1}: debugger statement detected`);
          }
        }
      } catch { /* skip */ }

      // Try to auto-format with Biome or Prettier
      try {
        // Check for Biome first
        const biomeCheck = process.platform === 'win32' ? 'where biome' : 'which biome';
        execSync(biomeCheck, { stdio: 'pipe' });
        execSync(`biome format --write "${filePath}"`, { stdio: 'pipe', timeout: 5000 });
      } catch {
        try {
          const prettierCheck = process.platform === 'win32' ? 'where prettier' : 'which prettier';
          execSync(prettierCheck, { stdio: 'pipe' });
          execSync(`prettier --write "${filePath}"`, { stdio: 'pipe', timeout: 5000 });
        } catch { /* no formatter available, that's fine */ }
      }
    }

    // MD frontmatter check
    if (ext === '.md') {
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        if (content.startsWith('---')) {
          const endIdx = content.indexOf('---', 3);
          if (endIdx === -1) {
            warnings.push('Unclosed YAML frontmatter (missing closing ---)');
          }
        }
      } catch { /* skip */ }
    }

    if (warnings.length > 0) {
      process.stderr.write(`[post-edit-quality] ${path.basename(filePath)}:\n`);
      for (const w of warnings) {
        process.stderr.write(`  - ${w}\n`);
      }
    }
  } catch (e) {
    process.stderr.write(`[post-edit-quality] ${e.message}\n`);
  }
  process.exit(0);
});
"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\doc-file-warning.js","content":"/**
 * PreToolUse hook (Write): warns about ad-hoc documentation files.
 * Files like NOTES.md, TODO.md, SCRATCH.md should go in structured directories,
 * not scattered at random locations.
 *
 * Non-blocking — warns only (exit 0).
 */
const path = require('path');

const AD_HOC_NAMES = new Set([
  'notes.md', 'todo.md', 'todos.md', 'scratch.md', 'temp.md',
  'draft.md', 'wip.md', 'ideas.md', 'brainstorm.md', 'log.md',
  'changelog.md', 'history.md',
]);

// These directories are structured — files here are fine
const STRUCTURED_DIRS = [
  'operations/engineering/records/',
  'operations/engineering/triage/',
  'library/',
  '.claude/',
];

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw);
    const filePath = (input.tool_input && input.tool_input.file_path) || '';
    if (!filePath) {
      process.exit(0);
      return;
    }

    const basename = path.basename(filePath).toLowerCase();
    if (!AD_HOC_NAMES.has(basename)) {
      process.exit(0);
      return;
    }

    // Check if it's in a structured directory
    const normalized = filePath.replace(/\\/g, '/');
    const inStructured = STRUCTURED_DIRS.some(dir => normalized.includes(dir));
    if (inStructured) {
      process.exit(0);
      return;
    }

    process.stderr.write(
      `[doc-file-warning] "${basename}" looks like an ad-hoc doc file.\n` +
      `  Consider placing it in operations/engineering/triage/ or operations/engineering/records/ instead.\n`
    );
  } catch (e) {
    process.stderr.write(`[doc-file-warning] ${e.message}\n`);
  }
  process.exit(0);
});
"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\pre-bash-commit-quality.js","content":"/**
 * PreToolUse hook (Bash): validates commit quality before git commit.
 *
 * Checks:
 * - Commit message follows conventional commit format (or is at least non-empty)
 * - No .env or credential files staged
 * - No --no-verify flag
 *
 * Blocks on critical issues (exit 2), warns on style issues (exit 0).
 */
let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw);
    const command = (input.tool_input && input.tool_input.command) || '';

    if (!/\bgit\s+commit\b/.test(command)) {
      process.exit(0);
      return;
    }

    // Block --no-verify
    if (/--no-verify\b/.test(command)) {
      process.stderr.write('[commit-quality] BLOCKED: --no-verify bypasses pre-commit hooks.\n');
      process.exit(2);
      return;
    }

    // Check for dangerous staged files
    const dangerousPatterns = ['.env', 'credentials', 'secret', '.pem', '.key'];
    const { execSync } = require('child_process');
    try {
      const staged = execSync('git diff --cached --name-only', { encoding: 'utf8', timeout: 5000 });
      const files = staged.trim().split('\n').filter(Boolean);
      for (const f of files) {
        const lower = f.toLowerCase();
        for (const pattern of dangerousPatterns) {
          if (lower.includes(pattern)) {
            process.stderr.write(`[commit-quality] WARNING: staged file "${f}" may contain secrets.\n`);
          }
        }
      }
    } catch { /* git not available or no staged files */ }

    // Check commit message format (extract from -m flag)
    const msgMatch = command.match(/-m\s+["']([^"']+)["']/);
    if (msgMatch) {
      const msg = msgMatch[1].trim();
      // Conventional commit: type(scope): description
      const conventional = /^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\(.+\))?:\s*.+/;
      if (!conventional.test(msg) && !msg.startsWith('Merge')) {
        process.stderr.write(
          `[commit-quality] NOTE: "${msg.slice(0, 50)}" doesn't follow conventional commit format.\n` +
          `  Expected: type(scope): description (e.g., "feat: add new skill")\n`
        );
      }
    }
  } catch (e) {
    process.stderr.write(`[commit-quality] ${e.message}\n`);
  }
  process.exit(0);
});
"}

