/**
 * Verify all hooks in settings.json resolve to existing scripts.
 */
const fs = require('fs');
const path = require('path');

const settings = JSON.parse(fs.readFileSync('.claude/settings.json', 'utf8'));
const hooks = settings.hooks;
let total = 0;
let missing = 0;

for (const [stage, entries] of Object.entries(hooks)) {
  console.log(`${stage}: ${entries.length} hook(s)`);
  for (const e of entries) {
    const cmd = e.hooks[0].command;
    const match = cmd.match(/node\s+"?([^"]+\.js)"?/);
    if (match) {
      const script = match[1];
      const exists = fs.existsSync(script);
      const async = e.hooks[0].async ? ' (async)' : '';
      console.log(`  ${e.matcher || '*'} -> ${path.basename(script)}${async} ${exists ? 'OK' : 'MISSING'}`);
      total++;
      if (!exists) missing++;
    }
  }
}

console.log(`\n${total} hooks, ${missing} missing`);
if (missing > 0) process.exit(1);
