{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\session-end-marker.js","content":"/**
 * SessionEnd hook: marks session as fully ended in the history log.
 * Distinct from session-end.js (Stop hook) which runs after each response.
 * This only fires once when the session actually terminates.
 */
const fs = require('fs');
const path = require('path');

const STATE_DIR = path.join(__dirname, '..', '..', '..', '..', 'operations', 'engineering', 'records', 'session-state');
const HISTORY_DIR = path.join(STATE_DIR, 'history');
const LATEST = path.join(STATE_DIR, 'latest.json');

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    const now = new Date();
    const dateStr = now.toISOString().slice(0, 10);

    // Read latest state to get session info
    let session = {};
    try {
      session = JSON.parse(fs.readFileSync(LATEST, 'utf8'));
    } catch { /* no state */ }

    const entry = {
      event: 'session_end',
      timestamp: now.toISOString(),
      session_id: session.session_id || 'unknown',
      stop_count: session.stop_count || 0,
    };

    fs.mkdirSync(HISTORY_DIR, { recursive: true });
    const logFile = path.join(HISTORY_DIR, `${dateStr}.jsonl`);
    fs.appendFileSync(logFile, JSON.stringify(entry) + '\n');

    process.stderr.write(`[session-end-marker] Session ended after ${entry.stop_count} interactions.\n`);
  } catch (e) {
    process.stderr.write(`[session-end-marker] ${e.message}\n`);
  }
  process.exit(0);
});
"}

